def transform(g):
    H,W=len(g),len(g[0])
    line=[r for r in range(H) if all(x==2 for x in g[r])][0]
    out=[[0]*W for _ in range(H)]
    out[line]=[2]*W
    above=[(r,c) for r in range(H) for c in range(W) if g[r][c]==4 and r<line]
    for r,c in [(r,c) for r in range(H) for c in range(W) if g[r][c]==4 and r>line]:
        out[r+1][c]=4
    for r,c in above:
        if r+1<line: out[r+1][c]=4
    if above:
        rr,cc=min(above,key=lambda d:abs(line-d[0]))
        for dr,dc in ((-1,-1),(-1,1)):
            r,c=line-1+dr,cc+dc
            while 0<=r<H and 0<=c<W:
                out[r][c]=4; r+=dr; c+=dc
    return out
